
import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart' as p;
import 'package:intl/intl.dart';

final money=NumberFormat.currency(locale:'es_CO',symbol:r'$',decimalDigits:0);
Future<Database>? _dbFuture;
Future<Database> db()=>_dbFuture??=_openDb();
Future<Database> _openDb() async {
 final path=p.join(await getDatabasesPath(),'finanzas_personales.db');
 return openDatabase(path,version:1,onCreate:(d,_) async {
  await d.execute('''CREATE TABLE clients(id TEXT PRIMARY KEY,name TEXT,principal INTEGER,agreed INTEGER,frequency TEXT,installment INTEGER,nextDue TEXT,notes TEXT,paid INTEGER DEFAULT 0)''');
  await d.execute('''CREATE TABLE products(sku TEXT PRIMARY KEY,name TEXT,category TEXT,subtype TEXT,cost INTEGER,price INTEGER,qty INTEGER DEFAULT 0)''');
  await d.execute('''CREATE TABLE movements(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT,type TEXT,category TEXT,description TEXT,amount INTEGER,currency TEXT DEFAULT 'COP',clientId TEXT,productSku TEXT,qty INTEGER DEFAULT 0,groupId TEXT)''');
  await d.execute('''CREATE TABLE payables(id INTEGER PRIMARY KEY AUTOINCREMENT,creditor TEXT,concept TEXT,total INTEGER,paid INTEGER DEFAULT 0,dueDate TEXT)''');
  await d.execute('''CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT)''');
  final raw=jsonDecode(await rootBundle.loadString('assets/seed.json'));
  for(final c in raw['clients']) { await d.insert('clients',c); }
  for(final x in raw['products']) { await d.insert('products',x); }
  for(final e in {'cashCOP':raw['cashCOP'],'cashUSD':raw['cashUSD'],'receivableFatherCOP':raw['receivableFatherCOP'],'penalty':jsonEncode(raw['penalty'])}.entries) { await d.insert('settings',{'key':e.key,'value':'${e.value}'}); }
 });
}
Future<int> setting(String k) async {final d=await db();final r=await d.query('settings',where:'key=?',whereArgs:[k]);return r.isEmpty?0:(int.tryParse('${r.first['value']}')??0);}
Future<void> moveCash(String type,String cat,String desc,int amount) async {
 final d=await db(); await d.transaction((tx) async {
  await tx.insert('movements',{'date':DateTime.now().toIso8601String(),'type':type,'category':cat,'description':desc,'amount':amount,'currency':'COP'});
  final r=await tx.query('settings',where:'key=?',whereArgs:['cashCOP']);final old=int.parse('${r.first['value']}');
  await tx.update('settings',{'value':'${type=='Ingreso'?old+amount:old-amount}'},where:'key=?',whereArgs:['cashCOP']);
 });
}
void main() async {WidgetsFlutterBinding.ensureInitialized();await db();runApp(const App());}
class App extends StatelessWidget {const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'Control Financiero',debugShowCheckedModeBanner:false,theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff173b57)),useMaterial3:true),home:const Home());}
class Home extends StatefulWidget {const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{
 int tab=0;final pages=const [Dashboard(),ClientsPage(),ProductsPage(),MovementsPage(),PayablesPage()];
 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Control financiero')),body:pages[tab],
 floatingActionButton:tab==1?FloatingActionButton.extended(onPressed:_newLoan,icon:const Icon(Icons.add),label:const Text('Préstamo')):tab==3||tab==4?FloatingActionButton(onPressed:tab==3?_newMove:_newPayable,child:const Icon(Icons.add)):null,
 bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const [
 NavigationDestination(icon:Icon(Icons.dashboard),label:'Resumen'),NavigationDestination(icon:Icon(Icons.people),label:'Cartera'),NavigationDestination(icon:Icon(Icons.inventory),label:'Inventario'),NavigationDestination(icon:Icon(Icons.swap_horiz),label:'Movimientos'),NavigationDestination(icon:Icon(Icons.receipt_long),label:'Por pagar')]));
 Future<void> _newLoan() async {final n=TextEditingController(),p0=TextEditingController(),t=TextEditingController(),q=TextEditingController(),f=TextEditingController(text:'Semanal');
 final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('Nuevo préstamo'),content:Column(mainAxisSize:MainAxisSize.min,children:[field(n,'Deudor'),field(p0,'Capital desembolsado',num:true),field(t,'Total pactado',num:true),field(q,'Valor cuota',num:true),field(f,'Frecuencia')]),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Guardar'))]));
 if(ok==true&&n.text.trim().isNotEmpty){final d=await db();final count=(await d.rawQuery('SELECT COUNT(*) n FROM clients')).first['n'] as int;final cap=int.tryParse(p0.text)??0;await d.insert('clients',{'id':'CLI-${(count+1).toString().padLeft(3,'0')}','name':n.text,'principal':cap,'agreed':int.tryParse(t.text)??cap,'frequency':f.text,'installment':int.tryParse(q.text)??0,'notes':'Nuevo registro'});if(cap>0)await moveCash('Gasto','Desembolso','Préstamo a ${n.text}',cap);setState((){});}
 }
 Future<void> _newMove() async {final desc=TextEditingController(),v=TextEditingController();String type='Gasto',cat='Otro';
 final ok=await showDialog<bool>(context:context,builder:(x)=>StatefulBuilder(builder:(x,ss)=>AlertDialog(title:const Text('Movimiento'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField(value:type,items:['Ingreso','Gasto'].map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(s)=>ss(()=>type=s!),),DropdownButtonFormField(value:cat,items:['Cobro cartera','Venta platería','Venta belleza','Desembolso','Compra inventario','Pago deuda','Otro'].map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(s)=>ss(()=>cat=s!)),field(desc,'Descripción'),field(v,'Valor COP',num:true)]),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Guardar'))])));
 if(ok==true){final a=int.tryParse(v.text)??0;if(a>0)await moveCash(type,cat,desc.text,a);setState((){});}
 }
 Future<void> _newPayable() async {final who=TextEditingController(),what=TextEditingController(),v=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('Deuda por pagar'),content:Column(mainAxisSize:MainAxisSize.min,children:[field(who,'A quién'),field(what,'Concepto'),field(v,'Valor total',num:true)]),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Guardar'))]));if(ok==true){final d=await db();await d.insert('payables',{'creditor':who.text,'concept':what.text,'total':int.tryParse(v.text)??0});setState((){});}}
}
Widget field(TextEditingController c,String label,{bool num=false})=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:c,keyboardType:num?TextInputType.number:TextInputType.text,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
Widget tile(String a,String b,IconData i)=>Card(child:ListTile(leading:Icon(i),title:Text(a),trailing:Text(b,style:const TextStyle(fontWeight:FontWeight.bold))));
class Dashboard extends StatelessWidget {const Dashboard({super.key});@override Widget build(BuildContext c)=>FutureBuilder<List<int>>(future:stats(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final a=s.data!;return ListView(padding:const EdgeInsets.all(14),children:[Text('Activos y caja',style:Theme.of(c).textTheme.headlineSmall),tile('Caja COP',money.format(a[0]),Icons.account_balance_wallet),tile('Cartera pendiente',money.format(a[1]),Icons.people),tile('Inventario a costo',money.format(a[2]),Icons.inventory),tile('Cuenta por cobrar familiar',money.format(a[3]),Icons.account_balance),tile('Total activos COP',money.format(a[0]+a[1]+a[2]+a[3]),Icons.assessment),tile('Divisa separada','USD ${a[4]}',Icons.currency_exchange),const Padding(padding:EdgeInsets.all(12),child:Text('Multa registrada: 25% diario después de las 4:00 p. m. sobre la cuota vencida. Desactivada hasta validar el pacto y la legalidad.'))]);});}
Future<List<int>> stats() async {final d=await db();final cash=await setting('cashCOP'),usd=await setting('cashUSD'),fam=await setting('receivableFatherCOP');final c=await d.rawQuery('SELECT COALESCE(SUM(agreed-paid),0) v FROM clients');final i=await d.rawQuery('SELECT COALESCE(SUM(cost*qty),0) v FROM products');return [cash,(c.first['v'] as num).toInt(),(i.first['v'] as num).toInt(),fam,usd];}
class ClientsPage extends StatefulWidget{const ClientsPage({super.key});@override State<ClientsPage> createState()=>_ClientsState();}
class _ClientsState extends State<ClientsPage>{@override Widget build(BuildContext c)=>FutureBuilder<List<Map<String,Object?>>>(future:db().then((d)=>d.query('clients',orderBy:'name')),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.map((r)=>Card(child:ListTile(title:Text('${r['name']}'),subtitle:Text('${r['frequency']} · Cuota ${money.format(r['installment'])}\\n${r['notes']}'),isThreeLine:true,trailing:Text(money.format((r['agreed'] as int)-(r['paid'] as int))),onTap:()=>_pay(c,r)))).toList());});
 Future<void> _pay(BuildContext c,Map<String,Object?> r)async{final v=TextEditingController();final ok=await showDialog<bool>(context:c,builder:(x)=>AlertDialog(title:Text('Abono: ${r['name']}'),content:field(v,'Valor recibido',num:true),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Registrar'))]));if(ok==true){final a=int.tryParse(v.text)??0;if(a>0){final d=await db();await d.transaction((tx)async{await tx.rawUpdate('UPDATE clients SET paid=paid+? WHERE id=?',[a,r['id']]);await tx.insert('movements',{'date':DateTime.now().toIso8601String(),'type':'Ingreso','category':'Cobro cartera','description':'Abono ${r['name']}','amount':a,'currency':'COP','clientId':r['id']});final z=await tx.query('settings',where:'key=?',whereArgs:['cashCOP']);await tx.update('settings',{'value':'${int.parse('${z.first['value']}')+a}'},where:'key=?',whereArgs:['cashCOP']);});setState((){});}}}}

class ProductsPage extends StatefulWidget{const ProductsPage({super.key});@override State<ProductsPage> createState()=>_ProductsState();}
class _ProductsState extends State<ProductsPage>{
 @override Widget build(BuildContext c)=>FutureBuilder<List<Map<String,Object?>>>(future:db().then((d)=>d.query('products',orderBy:'category,name')),builder:(c,s){
 if(!s.hasData)return const Center(child:CircularProgressIndicator());
 final rows=s.data!;
 return ListView(children:[
  Padding(padding:const EdgeInsets.all(12),child:FilledButton.icon(onPressed:()=>_bundleSale(c,rows),icon:const Icon(Icons.shopping_cart_checkout),label:const Text('Registrar venta de varios artículos'))),
  Padding(padding:const EdgeInsets.symmetric(horizontal:14,vertical:4),child:Text('Platería: ${rows.where((r)=>r['category']=='Platería' && r['subtype']=='Cadena').length} referencias de cadenas · ${rows.where((r)=>r['category']=='Platería' && r['subtype']=='Complemento').length} referencias de complementos',style:const TextStyle(fontWeight:FontWeight.w600))),
  ...rows.map((r)=>Card(child:ListTile(title:Text('${r['name']}'),subtitle:Text('${r['category']} · ${r['sku']}\\nCosto ${money.format(r['cost'])} · Venta ${money.format(r['price'])} · Stock ${r['qty']}'),isThreeLine:true,trailing:IconButton(icon:const Icon(Icons.sell),onPressed:()=>_sell(c,r)),onTap:()=>_stock(c,r))))
 ]);});
 Future<void> _stock(BuildContext c,Map<String,Object?> r)async{final v=TextEditingController(text:'${r['qty']}');final ok=await showDialog<bool>(context:c,builder:(x)=>AlertDialog(title:Text('Existencias: ${r['name']}'),content:field(v,'Unidades disponibles',num:true),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Guardar'))]));if(ok==true){final d=await db();await d.update('products',{'qty':int.tryParse(v.text)??0},where:'sku=?',whereArgs:[r['sku']]);setState((){});}}
 Future<void> _sell(BuildContext c,Map<String,Object?> r)async{final v=TextEditingController(text:'1');final ok=await showDialog<bool>(context:c,builder:(x)=>AlertDialog(title:Text('Venta: ${r['name']}'),content:field(v,'Cantidad',num:true),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Vender'))]));if(ok==true){final q=int.tryParse(v.text)??0;if(q>0&&q<=(r['qty'] as int)){await _recordSale([{'product':r,'qty':q}],c);}else{ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Stock insuficiente o cantidad incorrecta')));}}}
 Future<void> _bundleSale(BuildContext c,List<Map<String,Object?>> rows)async{
  final selected=<String>{}; final quantities=<String,TextEditingController>{for(final r in rows)r['sku'].toString():TextEditingController(text:'1')};
  final ok=await showDialog<bool>(context:c,builder:(x)=>StatefulBuilder(builder:(x,ss)=>AlertDialog(title:const Text('Venta de varios artículos'),content:SizedBox(width:420,height:480,child:ListView(children:rows.map((r){final sku='${r['sku']}';return CheckboxListTile(value:selected.contains(sku),onChanged:(v)=>ss(()=>v==true?selected.add(sku):selected.remove(sku)),title:Text('${r['name']}'),subtitle:Text('Stock ${r['qty']} · ${money.format(r['price'])}'),secondary:SizedBox(width:58,child:TextField(controller:quantities[sku],keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Cant.'))));}).toList())),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Registrar venta'))])));
  if(ok==true&&selected.isNotEmpty){final lines=<Map<String,dynamic>>[];for(final sku in selected){final r=rows.firstWhere((x)=>'${x['sku']}'==sku);final q=int.tryParse(quantities[sku]!.text)??0;if(q<=0||q>(r['qty'] as int)){ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('Cantidad inválida o stock insuficiente: ${r['name']}')));return;}lines.add({'product':r,'qty':q});}await _recordSale(lines,c);}
 }
 Future<void> _recordSale(List<Map<String,dynamic>> lines,BuildContext c)async{
  final d=await db();final group='VTA-${DateTime.now().microsecondsSinceEpoch}';
  await d.transaction((tx)async{int total=0;for(final line in lines){final r=line['product'] as Map<String,Object?>;final q=line['qty'] as int;final amount=(r['price'] as int)*q;total+=amount;await tx.rawUpdate('UPDATE products SET qty=qty-? WHERE sku=?',[q,r['sku']]);await tx.insert('movements',{'date':DateTime.now().toIso8601String(),'type':'Ingreso','category':'Venta ${r['category']}','description':'$group · ${r['name']} x$q','amount':amount,'currency':'COP','productSku':r['sku'],'qty':q,'groupId':group});}final z=await tx.query('settings',where:'key=?',whereArgs:['cashCOP']);await tx.update('settings',{'value':'${int.parse('${z.first['value']}')+total}'},where:'key=?',whereArgs:['cashCOP']);});
  setState((){});ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('Venta registrada en ${lines.length} líneas separadas · ${money.format(lines.fold<int>(0,(s,l)=>s+((l['product']['price'] as int)*(l['qty'] as int))))}')));
 }
}
