class _PayablesState extends State<PayablesPage>{@override Widget build(BuildContext c)=>FutureBuilder<List<Map<String,Object?>>>(future:db().then((d)=>d.query('payables',orderBy:'id DESC')),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.map((r)=>Card(child:ListTile(title:Text('${r['creditor']} · ${r['concept']}'),subtitle:Text('Total ${money.format(r['total'])} · Pagado ${money.format(r['paid'])}'),trailing:Text(money.format((r['total'] as int)-(r['paid'] as int))),onTap:()=>_pay(c,r)))).toList());});
 Future<void> _pay(BuildContext c,Map<String,Object?> r)async{final v=TextEditingController();final ok=await showDialog<bool>(context:c,builder:(x)=>AlertDialog(title:const Text('Registrar pago'),content:field(v,'Valor pagado',num:true),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Pagar'))]));if(ok==true){final a=int.tryParse(v.text)??0;if(a>0){final d=await db();await d.transaction((tx)async{await tx.rawUpdate('UPDATE payables SET paid=paid+? WHERE id=?',[a,r['id']]);await tx.insert('movements',{'date':DateTime.now().toIso8601String(),'type':'Gasto','category':'Pago deuda','description':'Pago a ${r['creditor']}','amount':a,'currency':'COP'});final z=await tx.query('settings',where:'key=?',whereArgs:['cashCOP']);await tx.update('settings',{'value':'${int.parse('${z.first['value']}')-a}'},where:'key=?',whereArgs:['cashCOP']);});setState((){});}}}}
